// Obtener los datos del producto
const item = $input.first().json;

// Convertir los valores nutricionales a números
const sugar = Number(item.sugars_100g);
const salt = Number(item.salt_100g);
const fat = Number(item.fat_100g);

// Evaluar si cada nutriente supera su umbral
const highSugar = Number.isFinite(sugar) && sugar > 22.5;
const highSalt = Number.isFinite(salt) && salt > 1.5;
const highFat = Number.isFinite(fat) && fat > 17.5;

// Contar los nutrientes altos
const highCount = [highSugar, highSalt, highFat].filter(Boolean).length;

// Clasificación según nutrientes
let nutrientVerdict;

if (highCount === 0) {
  nutrientVerdict = "healthy";
} else if (highCount === 1) {
  nutrientVerdict = "moderate";
} else {
  nutrientVerdict = "unhealthy";
}

// Clasificación según Nutri-Score
const nutriscore = String(item.nutriscore_grade || "").toLowerCase();

let scoreVerdict;

if (["a", "b"].includes(nutriscore)) {
  scoreVerdict = "healthy";
} else if (nutriscore === "c") {
  scoreVerdict = "moderate";
} else if (["d", "e"].includes(nutriscore)) {
  scoreVerdict = "unhealthy";
} else {
  scoreVerdict = null; // Nutri-Score desconocido o ausente
}

// Asignar un nivel de gravedad a cada clasificación
const severity = {
  healthy: 0,
  moderate: 1,
  unhealthy: 2
};

// Elegir la clasificación más desfavorable
let verdict = nutrientVerdict;

if (scoreVerdict !== null &&
    severity[scoreVerdict] > severity[verdict]) {
  verdict = scoreVerdict;
}

// Devolver los datos y resultados
return [{
  json: {
    ...item,
    high_sugar: highSugar,
    high_salt: highSalt,
    high_fat: highFat,
    high_nutrient_count: highCount,
    nutrient_verdict: nutrientVerdict,
    score_verdict: scoreVerdict,
    verdict
  }
}];

